function nonVues(metier,dejaVues=[]){const v=new Set(dejaVues);return NOUVEAUTES.filter(n=>(!metier||n.metiers.includes(metier))&&!v.has(n.id))}
const SYNONYMES={ordonnance:'prescription',medoc:'medicament',traitement:'medicament',dose:'administrer',donner:'administrer',scanner:'datamatrix',bip:'scanner',transmission:'releve',passation:'releve',tension:'constantes',temperature:'constantes',fievre:'constantes',sortir:'sortie',accueil:'arrivee',famille:'proches',mdp:'mot de passe',compte:'acces',planning:'plannings',salle:'bloc',operation:'intervention',cr:'compte rendu',vocal:'dicter'};
function chercher(question,metier){
 const mots=norm(question).split(' ').filter(w=>w.length>2&&!['comment','faire','pour','avec','une','des','les','est','que','qui','dans','mon','mes','sur'].includes(w));
 const etendus=[...new Set(mots.flatMap(w=>[w,...(SYNONYMES[w]?norm(SYNONYMES[w]).split(' '):[])]))];
 const sc=FICHES.map(f=>{const titre=norm(f.titre),cles=norm(f.cles),corps=norm(f.etapes.join(' '));let s=0;
  for(const w of etendus){const rac=w.slice(0,Math.max(4,w.length-2));if(titre.includes(rac))s+=5;if(cles.includes(rac))s+=3;if(corps.includes(rac))s+=1}
  if(s&&metier&&f.metiers.includes(metier))s+=2;return {f,s}}).filter(x=>x.s>0||!etendus.length);
 const pourMoi=f=>!metier||f.metiers.includes(metier);
 return sc.sort((a,b)=>b.s-a.s||(+pourMoi(b.f))-(+pourMoi(a.f))).map(x=>x.f).filter(f=>etendus.length||pourMoi(f));
}
return {FICHES,VISITES,visite,NOUVEAUTES,nonVues,chercher,norm};
